import {enterpriseModel} from './enterprise-models.js';
import {productProfile,configuredProduct} from './product-profiles.js';
export function deviceGuide(n,network,hub,nodes){const p=productProfile(n),state=network.localStatus(n),address=n.net.ip!=='0.0.0.0',path=address&&network.reachable(hub,n,n.net.vlan),ready=state.ok&&address&&path&&(p.serial?n.net.ssh:configuredProduct(n).commissioned);
 const used=new Set(nodes.map(x=>x.net.ip));let host=80;while(used.has('10.10.70.'+host)&&host<230)host++;const ip=address?n.net.ip:'10.10.70.'+host;
 const commands=p.family==='fortiswitch'?`config system interface\nedit mgmt\nset ip ${ip}/24\nset allowaccess ping https ssh\nnext\nend\nconfig router static\nedit 1\nset gateway 10.10.70.1\nnext\nend`:p.family==='aoscx'?`configure terminal\nhostname ACCESS-01\ninterface mgmt\nno ip dhcp\nip static ${ip}/24\ndefault-gateway 10.10.70.1\nexit\nssh server vrf mgmt\nend\nwrite memory`:p.family==='connectrix'?`switchname FABRIC-A\nipaddrset\n${ip}\n255.255.255.0\n10.10.70.1\nipaddrshow\n# Next: alicreate, zonecreate, cfgcreate, cfgenable. Type help.`:p.family==='nxos'?`configure terminal\nhostname NEXUS-01\ninterface mgmt0\nip address ${ip}/24\nno shutdown\nexit\nvrf context management\nip route 0.0.0.0/0 10.10.70.1\nexit\nfeature ssh\nend\ncopy running-config startup-config`:`configure terminal\nhostname POWERSWITCH-01\ninterface mgmt 1/1/1\nno ip address dhcp\nip address ${ip}/24\nno shutdown\nexit\nmanagement route 0.0.0.0/0 10.10.70.1\nip ssh server enable\nend\nwrite memory`;
 return {ready,profile:enterpriseModel(n),title:ready?'OPERATIONS':'INITIAL SETUP',commands,steps:[{ok:state.ok,text:state.ok?'Control plane ready':state.reason},{ok:address,text:p.serial?'Connect serial console and assign management IP. No IP or VLAN is needed for console access.':'Open the product setup GUI and configure its management network.'},{ok:p.serial?!!n.net.ssh:!!configuredProduct(n).commissioned,text:p.serial?'Set management route and SSH. Configure production VLANs on data ports separately.':'Complete the product setup pages and validate initial configuration.'},{ok:path,text:'Connect management Ethernet to the MGMT-SW access port on the chosen OOB fabric.'}],operations:p.family==='connectrix'?'Manage Fabric OS aliases, zones and active fabric configuration.':p.serial?'Use the console or SSH for port, VLAN and OOB management settings.':'Use the product manager for system settings. Data paths, storage mappings and WAN are validated independently from management access.'};}
